        _revertSelectorOnActiveRental(selector, from, to, tokenId);
    } // ... similar else-if checks for safeTransferFrom variants, ERC1155 transfers/approvals, enable/disable module ...

    else {
        // Additional blocked selectors
        if (selector == shared_set_approval_for_all_selector) {
            revert Errors.GuardPolicy_UnauthorizedSelector(
                shared_set_approval_for_all_selector
            );
        } // ... e1155_safe_batch_transfer_from_selector, gnosis_safe_set_guard_selector ...
        // Permit-style selectors (e.g. ERC721.permit) not blocked, transaction allowed
