    uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));
    uint256 quoteBalance = _QUOTE_TOKEN_.balanceOf(address(this));
    // ...
    if (baseInput == 0) {
        revert ErrNoBaseInput();
    }
    if (totalSupply() == 0) {
        // Bootstrap: initial supply
        if (quoteBalance == 0) {
            revert ErrZeroQuoteAmount();
        }
        shares = quoteBalance < DecimalMath.mulFloor(baseBalance, _I_) ?
            DecimalMath.divFloor(quoteBalance, _I_) : baseBalance;
        // Set _BASE_TARGET_ = shares.toUint112();
        // _QUOTE_TARGET_ = DecimalMath.mulFloor(shares, _I_).toUint112();
        // ...
        if (shares <= 2001) {
            revert ErrMintAmountNotEnough();
        }
        _mint(address(0), 1001);  // Vulnerable: mint locked LP shares to address(0)
        shares -= 1001;
    } else {
        // Normal case: compute shares based on input ratios
        // ...
    }
    _mint(to, shares);
    // _setReserve(baseBalance, quoteBalance);
    // emit BuyShares(to, shares, balanceOf(to));
