/// @param state The state
/// @param params The input parameters for liquidating a debt position
/// @return liquidatorProfitCollateralToken The profit in collateral tokens expected by the liquidator
function executeLiquidate(State storage state, LiquidateParams calldata params)
    external
    returns (uint256 liquidatorProfitCollateralToken)
{
    DebtPosition storage debtPosition = state.getDebtPosition(params.debtPositionId);
    // ... loanStatus, emit, collateralRatio ...
    uint256 collateralProtocolPercent = state.feeConfig.overdueCollateralProtocolPercent;
    uint256 assignedCollateral = state.getDebtPositionAssignedCollateral(debtPosition);
    uint256 debtInCollateralToken = state.debtTokenAmountToCollateralTokenAmount(debtPosition.futureValue);
    uint256 protocolProfitCollateralToken = 0;

    // profitable liquidation
    if (assignedCollateral > debtInCollateralToken) {
        uint256 liquidatorReward = Math.min(
            assignedCollateral - debtInCollateralToken,
            Math.mulDivUp(debtPosition.futureValue, state.feeConfig.liquidationRewardPercent, PERCENT)
        );
        liquidatorProfitCollateralToken = debtInCollateralToken + liquidatorReward;

        // split the remaining collateral between the protocol and the borrower, capped by the crLiquidation
        uint256 collateralRemainder = assignedCollateral - liquidatorProfitCollateralToken;

        // cap the collateral remainder to the liquidation collateral ratio
        uint256 collateralRemainderCap =
            Math.mulDivDown(debtInCollateralToken, state.riskConfig.crLiquidation, PERCENT);

        collateralRemainder = Math.min(collateralRemainder, collateralRemainderCap);

        protocolProfitCollateralToken = Math.mulDivDown(collateralRemainder, collateralProtocolPercent, PERCENT);
    } else {
        // unprofitable liquidation
        liquidatorProfitCollateralToken = assignedCollateral;
    }

    // ... borrowAToken transferFrom ...
    state.data.collateralToken.transferFrom(debtPosition.borrower, msg.sender, liquidatorProfitCollateralToken);
    state.data.collateralToken.transferFrom(
        debtPosition.borrower, state.feeConfig.feeRecipient, protocolProfitCollateralToken
    );
    // ... repay ...
}
```

### Synopsis

`Liquidate.executeLiquidate` caps the post-liquidator collateral remainder using the full liquidation collateral ratio instead of the remaining collateral above the liquidator payout. Permissionless liquidation of solvent overdue loans can therefore overcharge borrowers and transfer excessive collateral to the protocol fee recipient.

### Technical Details

In the profitable liquidation branch, the code computes:

- `assignedCollateral`: collateral allocated to the debt position;
- `debtInCollateralToken`: borrow debt value converted into collateral-token units;
- `liquidatorProfitCollateralToken`: collateral transferred to the liquidator, including the debt-equivalent amount plus liquidation reward;
- `collateralRemainder`: collateral left after the liquidator payout.

The protocol fee is then charged on the capped `collateralRemainder`:

```solidity
uint256 collateralRemainderCap =
Math.mulDivDown(debtInCollateralToken, state.riskConfig.crLiquidation, PERCENT);

collateralRemainder = Math.min(collateralRemainder, collateralRemainderCap);
```

The root cause is that `collateralRemainderCap` is calculated as:

```solidity
debtInCollateralToken * crLiquidation
```

but this value represents the maximum total collateral corresponding to the liquidation collateral ratio, not the maximum remaining collateral after the liquidator has already received `liquidatorProfitCollateralToken`.

Because the cap is applied to the remainder, it should be reduced by the liquidator payout. Otherwise, for non-underwater overdue loans with high collateralization, the protocol fee can be computed on up to an additional full debt-equivalent amount of collateral.

For example, with:

- `debtInCollateralToken = 1 WETH`;
- `crLiquidation = 150%`;
- `liquidatorProfitCollateralToken = 1.05 WETH`;
- large `assignedCollateral`.

The maximum total collateral that should be considered under the liquidation threshold is `1.5 WETH`. Since the liquidator already receives `1.05 WETH`, the remaining capped fee base should be:

```solidity
1.5 WETH - 1.05 WETH = 0.45 WETH
```

The current code instead caps the remainder at:

```solidity
1 WETH * 150% = 1.5 WETH
```

Thus the protocol fee can be charged on `1.5 WETH` of remainder instead of `0.45 WETH`, over-allocating collateral from the borrower.

### Verification Checklist

To verify this vulnerability from the code and documentation:

- Confirm that `debtInCollateralToken` is a collateral-token amount representing the debt value.
- Confirm that `liquidatorProfitCollateralToken` is transferred to the liquidator in the `state.data.collateralToken.transferFrom(debtPosition.borrower, msg.sender, liquidatorProfitCollateralToken)` statement in `Liquidate.executeLiquidate`.
- Confirm that `collateralRemainder` in the assignment `assignedCollateral - liquidatorProfitCollateralToken` in `Liquidate.executeLiquidate` is already net of `liquidatorProfitCollateralToken`.
- Confirm that `collateralRemainderCap` in the `Math.mulDivDown(debtInCollateralToken, state.riskConfig.crLiquidation, PERCENT)` computation in `Liquidate.executeLiquidate` is calculated as the full liquidation-ratio collateral value, not as the remaining amount after the liquidator payout.
- Confirm that `protocolProfitCollateralToken` in the `Math.mulDivDown(collateralRemainder, collateralProtocolPercent, PERCENT)` computation in `Liquidate.executeLiquidate` is calculated from the capped remainder.
- Confirm that `protocolProfitCollateralToken` is transferred from the borrower to `feeRecipient` in the `state.data.collateralToken.transferFrom(debtPosition.borrower, state.feeConfig.feeRecipient, protocolProfitCollateralToken)` statement in `Liquidate.executeLiquidate`.
- Confirm from protocol documentation or intended economics that the liquidation collateral ratio is a cap on total collateral considered, not an additional cap applied after liquidator compensation.

### Assumptions and Preconditions

- The target debt position is liquidatable because it is overdue.
- The borrower is not underwater, or is sufficiently overcollateralized, so `assignedCollateral` is materially greater than `debtInCollateralToken`.
- `collateralProtocolPercent` or `overdueCollateralProtocolPercent` is greater than zero.
- The liquidator has enough `borrowAToken` allowance/balance to repay `debtPosition.futureValue`.
- The collateral token transfer from the borrower succeeds.
- The protocol intends `crLiquidation` to cap the total liquidation collateral exposure, not to allow an additional full-ratio remainder after the liquidator payout.

### Proof of Concept

1. Assume the following protocol configuration:

   - `crLiquidation = 150e16`, i.e. 150%;
   - `overdueCollateralProtocolPercent = 20e16`, i.e. 20%;
   - `liquidationRewardPercent = 5e16`, i.e. 5%.

2. Assume an overdue but highly collateralized debt position:

   - `debtInCollateralToken = 1e18`, i.e. 1 WETH equivalent debt;
   - `assignedCollateral = 10e18`, i.e. 10 WETH assigned collateral.

3. In the profitable branch, the liquidator receives approximately:

```solidity
liquidatorProfitCollateralToken = 1.05e18
```

4. The collateral remainder is:

```solidity
collateralRemainder = 10e18 - 1.05e18 = 8.95e18
```

5. The current code computes the cap as:

```solidity
collateralRemainderCap = 1e18 * 150% = 1.5e18
```

6. Therefore, the protocol fee is charged on `1.5e18`:

```solidity
protocolProfitCollateralToken = 1.5e18 * 20% = 0.3e18
```

7. The correct cap should account for the liquidator payout already taken from the total capped collateral:

```solidity
totalCollateralCap = 1e18 * 150% = 1.5e18
remainingCap = 1.5e18 - 1.05e18 = 0.45e18
```

8. The intended protocol fee should therefore be:

```solidity
correctProtocolProfitCollateralToken = 0.45e18 * 20% = 0.09e18
```

9. The borrower is overcharged by:

```solidity
0.3e18 - 0.09e18 = 0.21e18 WETH
```

10. Any account can trigger this over-allocation by calling permissionless `liquidate` on the overdue debt position.

### Remediation

Cap the collateral remainder by the unused portion of the total liquidation collateral cap after the liquidator payout has already been accounted for.

```solidity
uint256 totalCollateralCap =
Math.mulDivDown(debtInCollateralToken, state.riskConfig.crLiquidation, PERCENT);
uint256 collateralRemainderCap = totalCollateralCap > liquidatorProfitCollateralToken
? totalCollateralCap - liquidatorProfitCollateralToken
: 0;
collateralRemainder = Math.min(collateralRemainder, collateralRemainderCap);
```

## Gross collateral payout is validated as liquidation profit in `executeLiquidate` of `Liquidate`

[src/libraries/actions/Liquidate.sol#L71-L126](https://github.com/evmbench-org/2024-06-size/blob/4c61f1a5d07e3a201c1990546dd8905b2d2ddf92/src/libraries/actions/Liquidate.sol#L71-L126)

```solidity
/// @notice Executes the liquidation of a debt position
/// @param state The state
/// @param params The input parameters for liquidating a debt position
/// @return liquidatorProfitCollateralToken The profit in collateral tokens expected by the liquidator
function executeLiquidate(State storage state, LiquidateParams calldata params)
    external
    returns (uint256 liquidatorProfitCollateralToken)
{
    DebtPosition storage debtPosition = state.getDebtPosition(params.debtPositionId);
    // ...
    uint256 assignedCollateral = state.getDebtPositionAssignedCollateral(debtPosition);
    uint256 debtInCollateralToken = state.debtTokenAmountToCollateralTokenAmount(debtPosition.futureValue);
    uint256 protocolProfitCollateralToken = 0;

    // profitable liquidation
    if (assignedCollateral > debtInCollateralToken) {
        uint256 liquidatorReward = Math.min(
            assignedCollateral - debtInCollateralToken,
            Math.mulDivUp(debtPosition.futureValue, state.feeConfig.liquidationRewardPercent, PERCENT)
        );
        liquidatorProfitCollateralToken = debtInCollateralToken + liquidatorReward;
        // ... remainder split ...
    } else {
        // unprofitable liquidation
        liquidatorProfitCollateralToken = assignedCollateral;
    }

    state.data.borrowAToken.transferFrom(msg.sender, address(this), debtPosition.futureValue);
    state.data.collateralToken.transferFrom(debtPosition.borrower, msg.sender, liquidatorProfitCollateralToken);
    state.data.collateralToken.transferFrom(
        debtPosition.borrower, state.feeConfig.feeRecipient, protocolProfitCollateralToken
    );
    // ...
    return liquidatorProfitCollateralToken;
}
```

### Synopsis

`Liquidate.executeLiquidate` returns the liquidator’s gross collateral payout as “profit”. The minimum-profit check therefore validates collateral received, not net profit after repaying debt, allowing liquidations to execute with zero or negative actual profit despite a positive `minimumCollateralProfit`.

### Technical Details

The highlighted liquidation logic conflates two different values:

1. **Gross collateral output** — the total collateral transferred to the liquidator.
2. **Net liquidation profit** — the excess collateral value received after accounting for the debt value repaid by the liquidator.

During the `state.data.borrowAToken.transferFrom(msg.sender, address(this), debtPosition.futureValue)` execution, the liquidator pays the full `debtPosition.futureValue` in borrow aTokens. The collateral-equivalent value of that repayment is already computed as `debtInCollateralToken`.

However, in the profitable branch, the assignment `liquidatorProfitCollateralToken = debtInCollateralToken + liquidatorReward` assigns:

```solidity
liquidatorProfitCollateralToken = debtInCollateralToken + liquidatorReward;
```

This value includes the debt-equivalent principal amount and is therefore the **gross payout**, not profit. The actual net collateral profit is only `liquidatorReward`.

The issue is worse in the unprofitable branch. At the assignment `liquidatorProfitCollateralToken = assignedCollateral` when `assignedCollateral <= debtInCollateralToken`, the function assigns:

```solidity
liquidatorProfitCollateralToken = assignedCollateral;
```

In this branch, the liquidator receives less collateral value than the debt they repay, so the actual net profit is zero or negative. Nevertheless, the returned value is the gross collateral received.

Because the returned `liquidatorProfitCollateralToken` is later used to validate `params.minimumCollateralProfit`, the protection does not enforce the documented minimum profit. Any liquidation where gross collateral output exceeds `minimumCollateralProfit` can pass even if the liquidator’s real net profit is below the requested minimum or negative.

### Verification Checklist

A security engineer can verify this issue by checking:

- `LiquidateParams.minimumCollateralProfit` is documented as minimum **profit**, not minimum gross collateral output.
- `executeLiquidate` returns `liquidatorProfitCollateralToken`.
- In the profitable branch, the assignment of `liquidatorProfitCollateralToken` to `debtInCollateralToken + liquidatorReward`.
- `debtInCollateralToken` represents the collateral-equivalent value of the debt repaid by the liquidator.
- The actual net profit in the profitable branch is only `liquidatorReward`, not `debtInCollateralToken + liquidatorReward`.
- In the unprofitable branch, the assignment of `liquidatorProfitCollateralToken` to `assignedCollateral` as “profit” even though `assignedCollateral <= debtInCollateralToken`.
- During the `state.data.borrowAToken.transferFrom(msg.sender, address(this), debtPosition.futureValue)` execution, the liquidator still pays the full debt amount.
- During the `state.data.collateralToken.transferFrom(debtPosition.borrower, msg.sender, liquidatorProfitCollateralToken)` execution, the liquidator receives only the gross collateral amount.
- There is no highlighted logic subtracting `debtInCollateralToken` from the returned value before the minimum-profit validation is applied.

### Assumptions and Preconditions

- The debt position is liquidatable according to the protocol’s liquidation rules.
- The liquidator supplies sufficient borrow aTokens and approval for line `HL:58`.
- The liquidator relies on `minimumCollateralProfit` according to its documented meaning: minimum net profit in collateral tokens.
- The gross collateral payout is greater than `minimumCollateralProfit`.
- The actual net profit is lower than `minimumCollateralProfit`, or negative.

### Proof of Concept

1. Assume:
   - Borrow token: USDC.
   - Collateral token: WETH.
   - Oracle price: `1 WETH = 1000 USDC`.
   - `debtPosition.futureValue = 1000 USDC`.
   - Therefore, `debtInCollateralToken = 1 WETH`.
   - `assignedCollateral = 0.9 WETH`.
   - The position is liquidatable because it is underwater or overdue.

2. A liquidator wants at least `0.01 WETH` net profit and calls liquidation with:

```solidity
minimumCollateralProfit = 0.01 ether
```

3. Since:

```solidity
assignedCollateral <= debtInCollateralToken
```

the liquidation enters the unprofitable branch.

4. In the unprofitable branch, where `liquidatorProfitCollateralToken` is set to `assignedCollateral`:

```solidity
liquidatorProfitCollateralToken = assignedCollateral = 0.9 ether
```

5. The `state.data.borrowAToken.transferFrom(msg.sender, address(this), debtPosition.futureValue)` transfers `1000 USDC` worth of borrow aTokens from the liquidator.

6. The `state.data.collateralToken.transferFrom(debtPosition.borrower, msg.sender, liquidatorProfitCollateralToken)` transfers only `0.9 WETH` of collateral to the liquidator.

7. The minimum-profit validation compares the returned value against the requested minimum:

```solidity
0.9 ether >= 0.01 ether
```

so the transaction passes.

8. The liquidator’s actual net result is:

```solidity
0.9 WETH received - 1.0 WETH debt equivalent paid = -0.1 WETH
```

The liquidation succeeds even though the liquidator requested a positive minimum profit.

### Remediation

Separate the gross collateral amount transferred to the liquidator from the net liquidation profit returned for minimum-profit validation. Use the gross amount only for the collateral transfer, and return the actual net profit.

```solidity
uint256 protocolProfitCollateralToken = 0;
       uint256 liquidatorCollateralTokenOut = 0;

liquidatorCollateralTokenOut = debtInCollateralToken + liquidatorReward;
       liquidatorProfitCollateralToken = liquidatorReward;

uint256 collateralRemainder = assignedCollateral - liquidatorCollateralTokenOut;

liquidatorCollateralTokenOut = assignedCollateral;
       liquidatorProfitCollateralToken = 0;

state.data.collateralToken.transferFrom(debtPosition.borrower, msg.sender, liquidatorCollateralTokenOut);
```

If the protocol wants `minimumCollateralProfit = 0` to also reject loss-making liquidations, add an explicit gross-output check requiring `liquidatorCollateralTokenOut >= debtInCollateralToken + params.minimumCollateralProfit`.

## Mutable pro-rata collateral reassignment compounds liquidation fees in `executeLiquidate` of `Liquidate`

[src/libraries/actions/Liquidate.sol#L71-L126](https://github.com/evmbench-org/2024-06-size/blob/4c61f1a5d07e3a201c1990546dd8905b2d2ddf92/src/libraries/actions/Liquidate.sol#L71-L126)

```solidity
/// @notice Executes the liquidation of a debt position
/// @param state The state
/// @param params The input parameters for liquidating a debt position
/// @return liquidatorProfitCollateralToken The profit in collateral tokens expected by the liquidator
function executeLiquidate(State storage state, LiquidateParams calldata params)
    external
    returns (uint256 liquidatorProfitCollateralToken)
{
    DebtPosition storage debtPosition = state.getDebtPosition(params.debtPositionId);
    // skipped: loan status, collateral ratio, emit, underwater check
    uint256 collateralProtocolPercent = state.feeConfig.collateralProtocolPercent; // simplified
    uint256 assignedCollateral = state.getDebtPositionAssignedCollateral(debtPosition);
    uint256 debtInCollateralToken = state.debtTokenAmountToCollateralTokenAmount(debtPosition.futureValue);
    uint256 protocolProfitCollateralToken = 0;

    // profitable liquidation
    if (assignedCollateral > debtInCollateralToken) {
        uint256 liquidatorReward = Math.min(
            assignedCollateral - debtInCollateralToken,
            Math.mulDivUp(debtPosition.futureValue, state.feeConfig.liquidationRewardPercent, PERCENT)
        );
        liquidatorProfitCollateralToken = debtInCollateralToken + liquidatorReward;

        // split the remaining collateral between the protocol and the borrower
        uint256 collateralRemainder = assignedCollateral - liquidatorProfitCollateralToken;
        // cap the collateral remainder to the liquidation collateral ratio
        uint256 collateralRemainderCap = Math.mulDivDown(debtInCollateralToken, state.riskConfig.crLiquidation, PERCENT);
        collateralRemainder = Math.min(collateralRemainder, collateralRemainderCap);
        protocolProfitCollateralToken = Math.mulDivDown(collateralRemainder, collateralProtocolPercent, PERCENT);
    } else {
        // unprofitable liquidation
        liquidatorProfitCollateralToken = assignedCollateral;
    }

    // transfers: only partial collateral from borrower
    state.data.borrowAToken.transferFrom(msg.sender, address(this), debtPosition.futureValue);
    state.data.collateralToken.transferFrom(debtPosition.borrower, msg.sender, liquidatorProfitCollateralToken);
    state.data.collateralToken.transferFrom(debtPosition.borrower, state.feeConfig.feeRecipient, protocolProfitCollateralToken);

    // repay full debt (reduces total debt)
    state.repayDebt(params.debtPositionId, debtPosition.futureValue);
}
```

### Synopsis

`Liquidate.executeLiquidate` in `Liquidate` recomputes a debt position’s assigned collateral from the borrower’s current aggregate collateral and debt. During sequential liquidations, unseized remainder collateral is reassigned to remaining debt positions, causing repeated fee assessment and excessive collateral loss for multi-position borrowers.

### Technical Details

At the calculation of `assignedCollateral` in `Liquidate.executeLiquidate` using `state.getDebtPositionAssignedCollateral(debtPosition)`, which derives the value from the borrower’s current total collateral (`state.data.collateralToken.balanceOf(debtPosition.borrower)`) and current total debt (`state.data.debtToken.balanceOf(debtPosition.borrower)`):

```solidity
assignedCollateral = borrowerCollateral * debtPosition.futureValue / borrowerTotalDebt
```

This value is not a fixed per-position allocation. It is dynamically recomputed every time a debt position is liquidated.

In a profitable liquidation, the function does not necessarily remove the full `assignedCollateral` from the borrower. It transfers only:

- the liquidator’s collateral amount, and
- the protocol fee amount.

Any borrower remainder from that debt position stays in the borrower’s `collateralToken.balanceOf`.

After the debt position is repaid, the borrower’s total debt decreases, but the unseized collateral remainder is still counted as borrower collateral. Therefore, when another debt position of the same borrower is liquidated, the calculation of `assignedCollateral` in `Liquidate.executeLiquidate` reallocates that previous remainder to the next debt position.

As a result, the same surplus collateral can be included in the liquidation fee base multiple times across sequential liquidations. The total collateral seized becomes dependent on debt-position fragmentation and liquidation order, rather than only on the borrower’s aggregate collateral, aggregate debt, and configured fee percentages.

This creates a compounding liquidation-fee effect against borrowers with multiple liquidatable debt positions.

### Verification Checklist

A security engineer should verify the following in the codebase:

- Confirm that the calculation of `assignedCollateral` in `Liquidate.executeLiquidate` calls `state.getDebtPositionAssignedCollateral(debtPosition)`.
- Confirm that `getDebtPositionAssignedCollateral` derives assigned collateral from current borrower-wide collateral and current borrower-wide debt.
- Confirm that liquidation does not debit the full `assignedCollateral` from the borrower when only part of it is paid to the liquidator/protocol.
- Confirm that the borrower remainder remains in `collateralToken.balanceOf(borrower)`.
- Confirm that after liquidation the debt position’s `futureValue` is reduced, lowering the denominator used by later `getDebtPositionAssignedCollateral` calls.
- Confirm there is no per-debt-position collateral snapshot or isolated collateral accounting preventing previously retained remainder from being reassigned to later liquidations.
- Confirm that multiple debt positions for the same borrower can be liquidated sequentially.

### Assumptions and Preconditions

- The borrower has more than one debt position.
- At least two of the borrower’s debt positions are liquidatable.
- The liquidation path is profitable, so a collateral remainder exists.
- The relevant protocol fee percentage on liquidation remainder is greater than zero.
- The borrower remainder from one liquidation remains counted as collateral for later debt-position collateral assignment.
- A liquidator can call `liquidate` sequentially for the borrower’s debt positions.

### Proof of Concept

Use simplified 1:1 debt/collateral pricing and ignore rounding.

Protocol configuration:

```solidity
collateralProtocolPercent = 10%;
liquidationRewardPercent = 0;
crLiquidation = 150%;
```

Initial borrower state:

```solidity
collateral = 240;
debtPositionA.futureValue = 100;
debtPositionB.futureValue = 100;
totalDebt = 200;
```

The borrower collateral ratio is `120%`, so the borrower is liquidatable.

### Remediation

Use position-specific collateral accounting instead of recomputing assigned collateral from mutable aggregate borrower balances during every liquidation.

The preferred fix is to snapshot or otherwise isolate each debt position’s collateral allocation, and ensure that collateral remainder from one liquidated position is not reassigned to other positions.

```solidity
uint256 assignedCollateral = state.getDebtPositionAssignedCollateralSnapshot(params.debtPositionId);
```

`getDebtPositionAssignedCollateralSnapshot` must return a per-position collateral allocation that is fixed or consistently updated independently from borrower-wide collateral remaining after previous liquidations.

## Fee-on-transfer ERC20 outbounds are over-reported in `_transferOutV5` of `THORChain_Router`

[chain/ethereum/contracts/THORChain_Router.sol#L209-L238](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/chain/ethereum/contracts/THORChain_Router.sol#L209-L238)

```solidity
  function _transferOutV5(TransferOutData memory transferOutPayload) private {
    if (transferOutPayload.asset == address(0)) {
      bool success = transferOutPayload.to.send(transferOutPayload.amount); // Send ETH.
      if (!success) {
        payable(address(msg.sender)).transfer(transferOutPayload.amount); // For failure, bounce back to vault & continue.
      }
    } else {
      _vaultAllowance[msg.sender][
        transferOutPayload.asset
      ] -= transferOutPayload.amount; // Reduce allowance

      (bool success, bytes memory data) = transferOutPayload.asset.call(
        abi.encodeWithSignature(
          "transfer(address,uint256)",
          transferOutPayload.to,
          transferOutPayload.amount
        )
      );

      require(success && (data.length == 0 || abi.decode(data, (bool))));
    }

    emit TransferOut(
      msg.sender,
      transferOutPayload.to,
      transferOutPayload.asset,
      transferOutPayload.amount,
      transferOutPayload.memo
    );
  }
```

### Synopsis

`THORChain_Router._transferOutV5` validates only ERC20 `transfer()` call success, not the actual amount received by the recipient. Fee-on-transfer tokens can deliver less than `transferOutPayload.amount` while the router emits `TransferOut` for the full amount, causing incorrect outbound settlement.

### Technical Details

In the ERC20 branch of `_transferOutV5`, the router reduces the vault allowance by `transferOutPayload.amount`, performs a low-level ERC20 `transfer`, and only checks whether the call succeeded and whether the optional return value is `true`:

The allowance decrement uses `_vaultAllowance[msg.sender][transferOutPayload.asset] -= transferOutPayload.amount` followed by the low-level `transferOutPayload.asset.call(abi.encodeWithSignature("transfer(address,uint256)", transferOutPayload.to, transferOutPayload.amount))` and `require(success && (data.length == 0 || abi.decode(data, (bool))))` check.

After that, the router emits `TransferOut` using the original requested amount:

The emission uses `emit TransferOut(msg.sender, transferOutPayload.to, transferOutPayload.asset, transferOutPayload.amount, transferOutPayload.memo)`.

This assumes that a successful ERC20 `transfer(to, amount)` always results in exactly `amount` tokens being credited to `to`. That assumption is false for fee-on-transfer / tax tokens. Such tokens commonly return `true` while deducting a transfer fee, burning part of the amount, or redirecting part of the amount to a fee collector.

As a result:

1. The router sends `amount` from its balance.
2. The recipient receives only `amount - fee`.
3. The router emits `TransferOut(..., amount, memo)`.
4. Bifrost / THORChain can observe the event as a successful outbound of the full amount.
5. The recipient is underpaid, while the protocol records the outbound as completed.

The root cause is that the highlighted ERC20 transfer path validates call-level success but does not validate recipient balance delta before emitting the settlement event.

### Verification Checklist

A security engineer can verify this issue statically by checking:

- In `_transferOutV5`, the ERC20 branch starts at the `else` block handling non-ETH assets (`transferOutPayload.asset != address(0)`).
- The vault allowance is decremented by `transferOutPayload.amount` via `_vaultAllowance[msg.sender][transferOutPayload.asset] -= transferOutPayload.amount`.
- The token transfer is performed with a raw low-level call to `transfer(address,uint256)` using `transferOutPayload.asset.call(abi.encodeWithSignature("transfer(address,uint256)", transferOutPayload.to, transferOutPayload.amount))`.
- The only validation is `success && optional bool return` via `require(success && (data.length == 0 || abi.decode(data, (bool))))`.
- There is no pre-transfer and post-transfer `balanceOf(transferOutPayload.to)` comparison.
- There is no check that the recipient actually received `transferOutPayload.amount`.
- The emitted `TransferOut` event reports `transferOutPayload.amount` directly via `emit TransferOut(msg.sender, transferOutPayload.to, transferOutPayload.asset, transferOutPayload.amount, transferOutPayload.memo)`.
- Protocol documentation states that `TransferOut` events are observed by Bifrost as completed EVM outbounds.

### Assumptions and Preconditions

- The affected asset is an ERC20 token that deducts a fee, tax, burn, or redistribution amount during outbound `transfer`.
- The ERC20 `transfer` call returns `true` or no return data, so the check at `HL:127` passes.
- The vault has sufficient `_vaultAllowance[msg.sender][asset]`.
- A vault calls `transferOutV5` or `batchTransferOutV5`, which internally executes the highlighted `_transferOutV5` logic.
- Bifrost / THORChain relies on the emitted `TransferOut` amount to observe and finalize outbound settlement.

### Proof of Concept

1. Consider an ERC20 token whose `transfer` deducts a 10% fee but still returns `true`:

```solidity
function transfer(address to, uint256 amount) external returns (bool) {
    balanceOf[msg.sender] -= amount;

    uint256 fee = amount / 10;
    balanceOf[to] += amount - fee;
    balanceOf[feeCollector] += fee;

    return true;
}
```

2. Assume the router holds `100` tokens for a vault and `_vaultAllowance[vault][token] == 100`.

3. The vault executes an outbound through `transferOutV5` or `batchTransferOutV5` with:

```solidity
TransferOutData({
    to: payable(user),
    asset: token,
    amount: 100,
    memo: "OUT:<inbound-hash>"
});
```

4. `_transferOutV5` enters the ERC20 branch.

5. The vault allowance is reduced by `100` via `_vaultAllowance[msg.sender][token] -= 100`.

6. The router calls `token.transfer(user, 100)` via the low-level `asset.call(abi.encodeWithSignature("transfer(address,uint256)", user, 100))`.

7. The token deducts `100` from the router, credits only `90` to `user`, and sends `10` to the fee collector.

8. The router accepts the transfer because the token returned `true` via the `require(success && (data.length == 0 || abi.decode(data, (bool))))` check.

9. The router emits:

```solidity
TransferOut(vault, user, token, 100, "OUT:<inbound-hash>")
```

10. The observed event reports a successful `100` token outbound, but the user actually received only `90`.

### Remediation

Validate the actual recipient balance delta for ERC20 outbounds before emitting `TransferOut`. If the recipient did not receive exactly `transferOutPayload.amount`, revert the transaction so no misleading outbound event is emitted.

Replace the ERC20 branch (`else` block) in `_transferOutV5` with:

```solidity
    } else {
      uint256 recipientBalanceBefore = iERC20(transferOutPayload.asset).balanceOf(
        transferOutPayload.to
      );

      _vaultAllowance[msg.sender][
        transferOutPayload.asset
      ] -= transferOutPayload.amount;

      (bool success, bytes memory data) = transferOutPayload.asset.call(
        abi.encodeWithSignature(
          "transfer(address,uint256)",
          transferOutPayload.to,
          transferOutPayload.amount
        )
      );

      require(success && (data.length == 0 || abi.decode(data, (bool))));

      uint256 recipientBalanceAfter = iERC20(transferOutPayload.asset).balanceOf(
        transferOutPayload.to
      );

      require(
        recipientBalanceAfter - recipientBalanceBefore == transferOutPayload.amount,
        "THORChain_Router: incomplete token delivery"
      );
    }
```

If fee-on-transfer tokens are intentionally unsupported for outbounds, this fix enforces that policy on-chain. If they must be supported, the router and Bifrost accounting should be redesigned to emit and process the verified net delivered amount instead.

## Cross-router sender-paid fee-on-transfer tokens undercharge vault allowance in `transferAllowance` / `_routerDeposit` of `THORChain_Router`

[chain/ethereum/contracts/THORChain_Router.sol#L162-L178](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/chain/ethereum/contracts/THORChain_Router.sol#L162-L178)

```solidity
  //############################## ALLOWANCE TRANSFERS ##############################

  // Use for "moving" assets between vaults (asgard<>ygg), as well "churning" to a new Asgard
  function transferAllowance(
    address router,
    address newVault,
    address asset,
    uint amount,
    string memory memo
  ) external nonReentrant {
    if (router == address(this)) {
      _adjustAllowances(newVault, asset, amount);
      emit TransferAllowance(msg.sender, newVault, asset, amount, memo);
    } else {
      _routerDeposit(router, newVault, asset, amount, memo);
    }
  }
```

### Synopsis

In cross-router `transferAllowance`, `_routerDeposit` debits only the nominal amount while the ERC20 transfer may deduct `amount + fee` from the router balance. Sender-paid fee tokens can make the source router undercollateralized, shifting transfer fees from the migrating vault to other vault balances.

### Technical Details

The cross-router migration path is entered through `transferAllowance` when `router != address(this)` in the else branch delegating to `_routerDeposit(router, newVault, asset, amount, memo)`. It delegates to `_routerDeposit`.

Inside `_routerDeposit`, the source vault allowance is reduced by exactly `_amount` via `_vaultAllowance[msg.sender][_asset] -= _amount;`, then the destination router is approved for exactly `_amount` via `safeApprove(_asset, _router, _amount);`, and the destination router is asked to pull `_amount` through `iROUTER(_router).depositWithExpiry(_vault, _asset, _amount, _memo, type(uint).max)`.

This assumes that the source router’s token balance decreases by exactly `_amount`. That assumption is false for fee-on-transfer tokens that charge the sender in addition to the transferred amount. For such tokens, `transferFrom(sourceRouter, destinationRouter, _amount)` can:

- reduce the source router’s token balance by `_amount + fee`;
- credit the destination router with `_amount`;
- reduce allowance by only `_amount`.

The router accounting only subtracts `_amount` from `_vaultAllowance[msg.sender][_asset]`. The extra `fee` is not deducted from the migrating vault’s allowance, even though it is removed from the source router’s pooled token balance. As a result, the source router’s remaining token balance becomes lower than the sum of remaining vault allowances.

An attacker can create their own source-router allowance, perform a cross-router migration for a sender-paid fee token, receive the full migrated amount on the destination router, and force the extra transfer fee to be absorbed by unrelated vaults whose allowances remain on the source router.

The root cause is that `_routerDeposit` performs allowance accounting using the requested nominal `_amount` instead of measuring and charging the actual decrease of the source router’s token balance caused by the external token transfer.

### Verification Checklist

A security engineer can verify the issue by checking the following:

- Confirm that `transferAllowance` calls `_routerDeposit` when `router != address(this)` in the else branch delegating to `_routerDeposit(router, newVault, asset, amount, memo)`.
- Confirm that `_routerDeposit` subtracts only `_amount` from `_vaultAllowance[msg.sender][_asset]` via `_vaultAllowance[msg.sender][_asset] -= _amount;`.
- Confirm that `_routerDeposit` approves the destination router via `safeApprove(_asset, _router, _amount);` and deposits exactly `_amount` via `iROUTER(_router).depositWithExpiry(_vault, _asset, _amount, _memo, type(uint).max)`.
- Confirm that `_routerDeposit` does not snapshot `iERC20(_asset).balanceOf(address(this))` before and after the destination `depositWithExpiry` call.
- Confirm that no later code reconciles the source router’s actual token balance decrease against the allowance decrease.
- Confirm that the destination router pulls tokens using ERC20 `transferFrom`, so token-specific fee logic executes during the migration.
- Confirm that sender-paid fee-on-transfer ERC20s can reduce the sender balance by more than the nominal `transferFrom` amount.

### Assumptions and Preconditions

- The asset is an ERC20 token that charges a sender-paid transfer fee, where the sender balance decreases by more than the requested transfer amount.
- The source router holds balances and allowances for the affected token.
- The attacker can obtain some `_vaultAllowance[attacker][_asset]`, for example by depositing the token to the source router using themselves as the vault.
- The attacker can call `transferAllowance` with `router` set to another valid router address.
- The destination router’s deposit path accepts the token transfer and credits the destination vault.
- The source router also holds other vault allowances for the same token, or will later need to satisfy other allowances from the same pooled token balance.

### Proof of Concept

1. Assume token `FEE` implements sender-paid fees:
   - `transferFrom(from, to, 100)` reduces `from` balance by `110`;
   - credits `to` with `100`;
   - sends or burns `10` as a transfer fee;
   - consumes allowance of only `100`.

2. The source router holds:
   - `1,000 FEE` backing a legitimate vault allowance;
   - `100 FEE` backing the attacker’s vault allowance.

   Total source router balance is `1,100 FEE`.

3. The attacker calls:

```solidity
sourceRouter.transferAllowance(
    address(destinationRouter),
    attacker,
    address(FEE),
    100,
    "MIGRATE"
);
```

4. In `_routerDeposit`, the source router decreases the attacker’s allowance by only `100` via `_vaultAllowance[msg.sender][_asset] -= _amount;`.

5. In `_routerDeposit`, the source router approves the destination router for `100` via `safeApprove(_asset, _router, _amount);`.

6. In `_routerDeposit`, the destination router pulls `100 FEE` from the source router via `iROUTER(_router).depositWithExpiry(_vault, _asset, _amount, _memo, type(uint).max)`.

7. The token charges the sender-paid fee:
   - source router balance decreases by `110`;
   - destination router receives `100`;
   - the fee of `10` is taken from the source router balance.

8. The attacker receives `100 FEE` of usable allowance on the destination router.

9. The source router now has only `990 FEE`, but the legitimate vault still has `1,000 FEE` of allowance recorded on the source router.

10. The source router is undercollateralized by `10 FEE`. The extra fee was not charged to the attacker’s allowance and is instead imposed on remaining vault balances.

### Remediation

Measure the actual source-router token balance decrease caused by the cross-router deposit and debit that amount from the caller’s allowance. This charges sender-paid transfer fees to the migrating vault instead of to unrelated vault balances.

```solidity
uint256 balanceBefore = iERC20(_asset).balanceOf(address(this));
safeApprove(_asset, _router, _amount);
iROUTER(_router).depositWithExpiry(
_vault,
_asset,
_amount,
_memo,
type(uint).max
);
uint256 spent = balanceBefore - iERC20(_asset).balanceOf(address(this));
require(spent >= _amount, "THORChain_Router: invalid token spend");
_vaultAllowance[msg.sender][_asset] -= spent;
```

## Unaccounted native-asset amount allows draining router ETH in `_transferOutV5` of `THORChain_Router`

[chain/ethereum/contracts/THORChain_Router.sol#L209-L238](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/chain/ethereum/contracts/THORChain_Router.sol#L209-L238)

```solidity
  function _transferOutV5(TransferOutData memory transferOutPayload) private {
    if (transferOutPayload.asset == address(0)) {
      bool success = transferOutPayload.to.send(transferOutPayload.amount); // Send ETH.
      if (!success) {
        payable(address(msg.sender)).transfer(transferOutPayload.amount); // For failure, bounce back to vault & continue.
      }
    } else {
      _vaultAllowance[msg.sender][
        transferOutPayload.asset
      ] -= transferOutPayload.amount; // Reduce allowance

      (bool success, bytes memory data) = transferOutPayload.asset.call(
        abi.encodeWithSignature(
          "transfer(address,uint256)",
          transferOutPayload.to,
          transferOutPayload.amount
        )
      );

      require(success && (data.length == 0 || abi.decode(data, (bool))));
    }

    emit TransferOut(
      msg.sender,
      transferOutPayload.to,
      transferOutPayload.asset,
      transferOutPayload.amount,
      transferOutPayload.memo
    );
  }
```

### Synopsis

`THORChain_Router._transferOutV5` sends `transferOutPayload.amount` of native ETH without verifying that this amount was supplied by the caller through `msg.value`. Any caller reaching this path can spend pre-existing ETH held by the router, bypassing the ERC20 allowance ledger entirely.

### Technical Details

In the highlighted native-asset branch, `_transferOutV5` treats `transferOutPayload.amount` as the amount of ETH to send:

```solidity
if (transferOutPayload.asset == address(0)) {
bool success = transferOutPayload.to.send(transferOutPayload.amount);
```

Unlike the ERC20 branch, the native-asset branch has no `_vaultAllowance` debit and no equivalent accounting check. The only intended source of native ETH for an outbound is the ETH supplied to the payable external wrapper through `msg.value`. However, the highlighted code never verifies that `transferOutPayload.amount` is equal to, or otherwise covered by, the ETH supplied for the current call.

As a result, the transfer is funded from the router contract’s entire native ETH balance, not from a caller-specific balance or an amount reserved for the current outbound. If the router contains any ETH before the call, an arbitrary caller can submit a native-asset `TransferOutData` payload with `asset == address(0)`, `amount` equal to the router’s ETH balance, and `msg.value == 0`. The router will send that ETH to the caller-controlled recipient.

This is a native-asset authorization/accounting bypass: ERC20 outbounds are limited by `_vaultAllowance[msg.sender][asset]`, while native outbounds are limited only by the router’s current ETH balance.

### Verification Checklist

A security engineer can verify the issue statically by checking:

- `_transferOutV5` native branch (if `transferOutPayload.asset == address(0)`) does not check `msg.value`.
- The `transferOutPayload.to.send(transferOutPayload.amount)` statement in the native branch sends `transferOutPayload.amount`, not `msg.value` or a value already reserved for this specific outbound.
- The native branch does not debit `_vaultAllowance` or any other per-vault native balance.
- The ERC20 branch has allowance accounting via the `_vaultAllowance[msg.sender][transferOutPayload.asset] -= transferOutPayload.amount` statement, but the native branch has no equivalent protection.
- Public/external payable wrappers can reach `_transferOutV5` using user-supplied `TransferOutData`.
- The router can hold native ETH, whether through payable functions, overfunded calls, or forced ETH transfers.
- There is no cumulative native-amount accounting for batched native outbounds that proves the sum of native payload amounts equals the current call’s `msg.value`.

### Assumptions and Preconditions

- The router has a positive native ETH balance before the attacker’s call.
- The attacker can call a public/external function that reaches `_transferOutV5`.
- The attacker supplies a payload with `asset == address(0)`.
- The attacker-controlled recipient can receive ETH.
- No off-chain validation can prevent the on-chain ETH transfer once the transaction is executed.

### Proof of Concept

1. Assume the router contains `10 ETH` before the attacker’s transaction.

2. The attacker prepares the following native-asset outbound payload:

```solidity
TransferOutData({
    to: payable(attacker),
    asset: address(0),
    amount: 10 ether,
    memo: "OUT:fake"
});
```

3. The attacker calls the public wrapper that invokes `_transferOutV5`, sending no ETH:

```solidity
router.transferOutV5{value: 0}(payload);
```

4. `_transferOutV5` enters the native-asset branch because `asset == address(0)`.

5. The router executes `transferOutPayload.to.send(transferOutPayload.amount)` in the native-asset branch of `_transferOutV5`.

6. The transfer is funded from the router’s existing ETH balance, not from `msg.value`.

7. The attacker receives `10 ETH`.

8. No native allowance or caller-specific balance was checked or decremented.

### Remediation

Native outbounds must be explicitly accounted against the ETH supplied in the current call. The preferred fix is to aggregate native amounts in the external wrappers, require the aggregate to equal `msg.value`, and pass a remaining native budget into `_transferOutV5` so it cannot consume pre-existing router ETH.

Corrected highlighted core logic:

```solidity
function _transferOutV5(
TransferOutData memory transferOutPayload,
uint256 nativeAmountAvailable
) private returns (uint256 nativeAmountSpent) {
if (transferOutPayload.asset == address(0)) {
require(
transferOutPayload.amount <= nativeAmountAvailable,
"THORChain_Router: insufficient native value"
);
nativeAmountSpent = transferOutPayload.amount;
(bool success, ) = transferOutPayload.to.call{
value: transferOutPayload.amount
}("");
require(success, "THORChain_Router: native transfer failed");
} else {
_vaultAllowance[msg.sender][
transferOutPayload.asset
] -= transferOutPayload.amount;
(bool success, bytes memory data) = transferOutPayload.asset.call(
abi.encodeWithSignature(
"transfer(address,uint256)",
transferOutPayload.to,
transferOutPayload.amount
)
);
require(success && (data.length == 0 || abi.decode(data, (bool))));
}
emit TransferOut(
msg.sender,
transferOutPayload.to,
transferOutPayload.asset,
transferOutPayload.amount,
transferOutPayload.memo
);
}
```

The external single-transfer wrapper should pass `msg.value` as the available native amount and require full consumption. The batch wrapper should sum all native-asset payload amounts and require that sum to equal `msg.value` before processing.

## Unconditional `TransferOut` Emission After Failed ETH Delivery in `_transferOutV5` of `THORChain_Router`

[ethereum/contracts/THORChain_Router.sol#L209-L238](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/ethereum/contracts/THORChain_Router.sol#L209-L238)

```solidity
  function _transferOutV5(TransferOutData memory transferOutPayload) private {
    if (transferOutPayload.asset == address(0)) {
      bool success = transferOutPayload.to.send(transferOutPayload.amount); // Send ETH.
      if (!success) {
        payable(address(msg.sender)).transfer(transferOutPayload.amount); // For failure, bounce back to vault & continue.
      }
    } else {
      _vaultAllowance[msg.sender][
        transferOutPayload.asset
      ] -= transferOutPayload.amount; // Reduce allowance

      (bool success, bytes memory data) = transferOutPayload.asset.call(
        abi.encodeWithSignature(
          "transfer(address,uint256)",
          transferOutPayload.to,
          transferOutPayload.amount
        )
      );

      require(success && (data.length == 0 || abi.decode(data, (bool))));
    }

    emit TransferOut(
      msg.sender,
      transferOutPayload.to,
      transferOutPayload.asset,
      transferOutPayload.amount,
      transferOutPayload.memo
    );
  }
```

### Synopsis

`THORChain_Router._transferOutV5` refunds ETH to the vault when recipient delivery fails, but still emits a successful `TransferOut` event. Off-chain Bifrost observers can interpret the log as a completed outbound, causing THORChain state to diverge from actual EVM value flow.

### Technical Details

In the highlighted `_transferOutV5` implementation, ETH outbounds are handled by calling `send` to the requested recipient:

- The ETH `send` operation to `transferOutPayload.to` with `transferOutPayload.amount` attempts delivery.
- If the send fails, the refund block transfers the ETH back to `msg.sender` (the vault).
- Execution then continues to the unconditional `emit TransferOut(msg.sender, transferOutPayload.to, transferOutPayload.asset, transferOutPayload.amount, transferOutPayload.memo)` statement.

This means the emitted event represents a successful outbound payment to `transferOutPayload.to` even when that address received no ETH. The event has no success flag and no indication that the value was refunded to the vault.

Because THORChain’s off-chain observation flow relies on router-emitted `TransferOut` logs to post outbound observations, this creates an event-state divergence: the EVM state shows the recipient was not paid, while the protocol-facing event stream says the outbound was completed.

The issue is especially dangerous in `batchTransferOutV5`, because `_transferOutV5` is called repeatedly and each failed ETH delivery still produces a normal-looking `TransferOut` event. Off-chain parsers cannot distinguish failed refunded items from successfully delivered items using the event alone.

### Verification Checklist

A security engineer can verify the vulnerability by checking the following:

- Confirm that the ETH `send` call to `transferOutPayload.to` uses `address.send`, which returns `false` on failure instead of reverting.
- Confirm that the refund path handles failed delivery by transferring `transferOutPayload.amount` back to `msg.sender` (the vault).
- Confirm that there is no `return`, `revert`, or conditional guard after the refund path.
- Confirm that the `emit TransferOut(msg.sender, transferOutPayload.to, transferOutPayload.asset, transferOutPayload.amount, transferOutPayload.memo)` statement always executes regardless of whether the ETH delivery succeeded or was refunded.
- Confirm that the `TransferOut` event schema does not include a delivery success/failure indicator.
- Confirm that Bifrost / off-chain parser logic treats router `TransferOut` logs as completed outbound observations and does not verify actual ETH receipt by `transferOutPayload.to`.
- Confirm that `batchTransferOutV5` calls `_transferOutV5` for each item, so the same misleading event can be emitted inside batches.

### Assumptions and Preconditions

- The outbound asset is native ETH, i.e. `transferOutPayload.asset == address(0)`.
- The recipient is a contract whose `receive` / `fallback` reverts or requires more than the 2300 gas stipend provided by `send`.
- The vault honestly calls `transferOutV5` or `batchTransferOutV5` to execute an outbound.
- The refund to `msg.sender` succeeds.
- Off-chain THORChain/Bifrost processing relies on the emitted `TransferOut` event as evidence of successful outbound delivery.

### Proof of Concept

1. Deploy a recipient contract that rejects ETH:

```solidity
contract RejectETH {
    receive() external payable {
        revert("reject");
    }
}
```

2. A THORChain outbound is prepared to send ETH to the `RejectETH` contract.

3. The vault calls `transferOutV5` or includes the item in `batchTransferOutV5` with:

```solidity
TransferOutData({
    to: payable(address(rejectETH)),
    asset: address(0),
    amount: 1 ether,
    memo: "OUT:<inbound-hash>"
})
```

4. Inside `_transferOutV5`, the `transferOutPayload.to.send(transferOutPayload.amount)` call attempts delivery.

5. The recipient rejects ETH, so `success == false`.

6. The refund operation `payable(address(msg.sender)).transfer(transferOutPayload.amount)` returns the ETH to the vault.

7. Despite the recipient receiving `0 ETH`, execution reaches the `emit TransferOut(...)` statement and emits:

```solidity
TransferOut(vault, rejectETH, address(0), 1 ether, "OUT:<inbound-hash>")
```

8. Bifrost observes the event and may report the outbound as completed, while actual EVM value flow shows the recipient was never paid.

### Remediation

Do not emit `TransferOut` when ETH delivery fails and the amount is refunded to the vault. The minimal fix is to exit `_transferOutV5` immediately after refunding a failed ETH transfer.

```solidity
function _transferOutV5(TransferOutData memory transferOutPayload) private {
if (transferOutPayload.asset == address(0)) {
bool success = transferOutPayload.to.send(transferOutPayload.amount); // Send ETH.
if (!success) {
payable(address(msg.sender)).transfer(transferOutPayload.amount); // For failure, bounce back to vault & continue.
return;
}
} else {
_vaultAllowance[msg.sender][
transferOutPayload.asset
] -= transferOutPayload.amount; // Reduce allowance

(bool success, bytes memory data) = transferOutPayload.asset.call(
abi.encodeWithSignature(
"transfer(address,uint256)",
transferOutPayload.to,
transferOutPayload.amount
)
);

require(success && (data.length == 0 || abi.decode(data, (bool))));
}

emit TransferOut(
msg.sender,
transferOutPayload.to,
transferOutPayload.asset,
transferOutPayload.amount,
transferOutPayload.memo
);
}
```

## ERC20 `TransferOut` Event Overstates Net Recipient Credit in `_transferOutV5` of `THORChain_Router`

[ethereum/contracts/THORChain_Router.sol#L209-L238](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/ethereum/contracts/THORChain_Router.sol#L209-L238)

```solidity
  function _transferOutV5(TransferOutData memory transferOutPayload) private {
    if (transferOutPayload.asset == address(0)) {
      bool success = transferOutPayload.to.send(transferOutPayload.amount); // Send ETH.
      if (!success) {
        payable(address(msg.sender)).transfer(transferOutPayload.amount); // For failure, bounce back to vault & continue.
      }
    } else {
      _vaultAllowance[msg.sender][
        transferOutPayload.asset
      ] -= transferOutPayload.amount; // Reduce allowance

      (bool success, bytes memory data) = transferOutPayload.asset.call(
        abi.encodeWithSignature(
          "transfer(address,uint256)",
          transferOutPayload.to,
          transferOutPayload.amount
        )
      );

      require(success && (data.length == 0 || abi.decode(data, (bool))));
    }

    emit TransferOut(
      msg.sender,
      transferOutPayload.to,
      transferOutPayload.asset,
      transferOutPayload.amount,
      transferOutPayload.memo
    );
  }
```

### Synopsis

`THORChain_Router._transferOutV5` emits `TransferOut` with the requested ERC20 amount, but does not verify the recipient’s actual balance increase. Fee-on-transfer or deflationary tokens can make Bifrost observe a completed outbound for more tokens than the recipient received.

### Technical Details

In the highlighted ERC20 branch of `_transferOutV5`, the router decrements the caller vault allowance by `transferOutPayload.amount` and performs a low-level ERC20 `transfer`:

- allowance is reduced by the requested amount where `_vaultAllowance[msg.sender][transferOutPayload.asset]` is decremented by `transferOutPayload.amount`;
- the token transfer is executed where the low-level call to `transferOutPayload.asset.transfer(transferOutPayload.to, transferOutPayload.amount)` is performed;
- only call success and optional boolean return data are checked where `require(success && (data.length == 0 || abi.decode(data, (bool))))` is executed;
- the emitted `TransferOut` event reports `transferOutPayload.amount` where the `amount` parameter in `emit TransferOut(...)` uses `transferOutPayload.amount`.

This assumes that a successful ERC20 `transfer(to, amount)` always increases `to`'s balance by exactly `amount`. That assumption is false for fee-on-transfer, tax, burn, reflection, or deflationary tokens. Such tokens can return `true` while crediting the recipient with less than `amount`.

Because Bifrost and THORChain's off-chain flow rely on router-emitted `TransferOut` logs to observe outbound completion, the event can report an amount larger than the actual recipient-received amount. The on-chain token state and the off-chain observed outbound state diverge.

The root cause is that the event amount is derived from the requested transfer amount rather than the recipient's actual balance delta.

### Verification Checklist

A security engineer can verify the issue statically by checking the following:

- Confirm that in the ERC20 branch, `_vaultAllowance[msg.sender][asset]` is decremented by `transferOutPayload.amount` where `_vaultAllowance[msg.sender][transferOutPayload.asset]` is decremented by `transferOutPayload.amount`.
- Confirm that the ERC20 transfer where the low-level call to `transferOutPayload.asset.transfer(transferOutPayload.to, transferOutPayload.amount)` is performed uses the requested amount.
- Confirm that the only validation where `require(success && (data.length == 0 || abi.decode(data, (bool))))` is executed checks low-level call success and optional boolean return data.
- Confirm there is no `balanceOf(transferOutPayload.to)` check before and after the transfer in the highlighted section.
- Confirm that the `TransferOut` event where `emit TransferOut(...)` is called emits `transferOutPayload.amount` where the `amount` parameter uses `transferOutPayload.amount`.
- Confirm from the protocol documentation that off-chain observers parse `TransferOut` logs as outbound completion signals.
- Confirm that a supported or processable ERC20 may have fee-on-transfer, burn, tax, reflection, or other mechanics where recipient balance delta is less than the transfer amount.

### Assumptions and Preconditions

- The affected outbound asset is an ERC20 token whose `transfer` can succeed while crediting the recipient with less than the requested amount.
- The calling vault has sufficient `_vaultAllowance[msg.sender][asset]` for `transferOutPayload.amount`.
- The router holds enough token balance for the transfer to execute.
- Bifrost or another off-chain component treats the emitted `TransferOut` event amount as the completed outbound amount.
- The outbound is executed through `transferOutV5` or `batchTransferOutV5`, both of which use the highlighted `_transferOutV5` logic.

### Proof of Concept

1. Consider an ERC20 token that burns or taxes 10% on every transfer while still returning `true`.

2. The router has `1,000` units of this token assigned as allowance to a vault.

3. The vault executes an outbound through `_transferOutV5` with:

```solidity
TransferOutData({
    to: payable(alice),
    asset: address(feeToken),
    amount: 1000,
    memo: "OUT:<inbound-hash>"
})
```

4. The highlighted code decrements the vault allowance by `1,000` where `_vaultAllowance[msg.sender][transferOutPayload.asset]` is decremented.

5. The router calls `feeToken.transfer(alice, 1000)`.

6. The token transfer succeeds, but due to the 10% transfer fee:
   - router balance decreases by `1,000`;
   - Alice's balance increases by only `900`;
   - `100` tokens are burned or redirected as a fee.

7. The check where `require(success && (data.length == 0 || abi.decode(data, (bool))))` is executed passes because the token returned success.

8. The router emits:

```solidity
TransferOut(vault, alice, feeToken, 1000, "OUT:<inbound-hash>")
```

9. Off-chain observers see an outbound of `1,000` tokens, while Alice actually received only `900`.

### Remediation

Measure the recipient's actual token balance delta for ERC20 outbounds and ensure the emitted amount reflects the actual credited amount. If the protocol requires exact outbound delivery, revert when the recipient receives less than the requested amount.

```solidity
uint256 safeAmount = transferOutPayload.amount;
if (transferOutPayload.asset == address(0)) {
bool success = transferOutPayload.to.send(transferOutPayload.amount); // Send ETH.
if (!success) {
payable(address(msg.sender)).transfer(transferOutPayload.amount); // For failure, bounce back to vault & continue.
}
} else {
_vaultAllowance[msg.sender][
transferOutPayload.asset
] -= transferOutPayload.amount; // Reduce allowance
uint256 recipientBalanceBefore = iERC20(transferOutPayload.asset).balanceOf(
transferOutPayload.to
);
(bool success, bytes memory data) = transferOutPayload.asset.call(
abi.encodeWithSignature(
"transfer(address,uint256)",
transferOutPayload.to,
transferOutPayload.amount
)
);
require(success && (data.length == 0 || abi.decode(data, (bool))));
uint256 recipientBalanceAfter = iERC20(transferOutPayload.asset).balanceOf(
transferOutPayload.to
);
safeAmount = recipientBalanceAfter - recipientBalanceBefore;
require(safeAmount == transferOutPayload.amount, "THORChain_Router: invalid ERC20 received amount");
safeAmount,
```

## Non-reverting/no-op aggregator calls are treated as successful in `transferOutAndCall` of `THORChain_Router`

[ethereum/contracts/THORChain_Router.sol#L255-L293](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/ethereum/contracts/THORChain_Router.sol#L255-L293)

```solidity
// Vulnerable transferOutAndCall in THORChain_Router
// Low-level call treated as success if no revert, skips fallback, emits success event
function transferOutAndCall(
  address payable aggregator,
  address finalToken,
  address to,
  uint256 amountOutMin,
  string memory memo
) public payable {
  uint256 _safeAmount = msg.value;
  // MISSING: require(aggregator.code.length > 0, "invalid aggregator");
  // MISSING: balance snapshot of finalToken or ETH for `to`
  (bool erc20Success, ) = aggregator.call{value: _safeAmount}(
    abi.encodeWithSignature("swapOut(address,address,uint256)", finalToken, to, amountOutMin)
  );
  if (!erc20Success) {
    // Fallback ETH only if call reverts
    payable(to).send(_safeAmount);
    // ... bounce to msg.sender if send fails
  }
  // Emits success even for no-op aggregator (no tokens sent)
  emit TransferOutAndCall(msg.sender, aggregator, _safeAmount, finalToken, to, amountOutMin, memo);
}
```

### Synopsis

`THORChain_Router.transferOutAndCall` treats a low-level aggregator call as successful solely because it does not revert. A no-op, EOA, fallback-only, or failure-swallowing aggregator can receive native assets, perform no swap, skip fallback refund logic, and still emit a successful outbound event.

### Technical Details

In `transferOutAndCall`, the router forwards the full `msg.value` to `aggregator` using a low-level call:

- the result of the low-level `aggregator.call{value: _safeAmount}` only indicates whether the EVM call reverted;
- it does not prove that `swapOut(address,address,uint256)` was actually implemented;
- it does not prove that the recipient received `finalToken`;
- it does not validate returned data or output amount;
- it does not check that `aggregator` contains contract code.

A low-level call to an EOA succeeds if value transfer succeeds. Similarly, a contract with a payable fallback, an incorrectly implemented `swapOut`, or an aggregator that catches downstream swap failures and returns normally will make `erc20Success == true`.

Because the fallback branch at the `if (!erc20Success)` condition executes only when `erc20Success == false`, a non-reverting logical swap failure bypasses the native-asset fallback path entirely. The ETH remains with the aggregator/no-op target, the recipient receives neither the desired token nor fallback ETH, and the function still emits `TransferOutAndCall` in the event emission statement after the call.

This is distinct from a reverting aggregator path: here the router never enters the failure handling path because the EVM-level call succeeded.

### Verification Checklist

A security engineer can verify this issue statically by checking:

- The low-level `aggregator.call{value: _safeAmount}(...)` in `transferOutAndCall`.
- The returned boolean is used as the only success criterion.
- There is no `aggregator.code.length` validation before the call.
- There is no balance snapshot of `finalToken` or native asset for `to` before and after the call.
- There is no validation that `to` received at least `amountOutMin`.
- The fallback ETH path in the `if (!erc20Success)` branch is executed only when the low-level call reverts/fails.
- The `TransferOutAndCall` event emission occurs after a non-reverting aggregator call even if no output was delivered.

### Assumptions and Preconditions

- `transferOutAndCall` is called with `msg.value > 0`.
- The selected `aggregator` can be a non-compliant contract, fallback-only contract, EOA, or an aggregator implementation that catches internal swap failures without reverting.
- The router event is used by off-chain observers as an outbound completion signal.
- The recipient expects either the swapped `finalToken` or fallback native asset.
- No admin or owner account needs to act maliciously once such an aggregator target is used.

### Proof of Concept

1. Deploy or select a non-compliant payable aggregator:

```solidity
contract NoOpAggregator {
    function swapOut(address, address, uint256) external payable {
        // Accept ETH and return successfully without transferring any token.
    }
}
```

2. A vault calls:

```solidity
transferOutAndCall{value: 1 ether}(
    payable(address(noOpAggregator)),
    finalToken,
    recipient,
    1,
    "OUT:example"
);
```

3. At the low-level `aggregator.call{value: _safeAmount}`, the router sends `1 ether` to `NoOpAggregator`.

4. `NoOpAggregator.swapOut` returns normally, so `erc20Success == true`.

5. The router skips the failure branch at the `if (!erc20Success)` condition.

6. The recipient receives no `finalToken` and no fallback ETH.

7. The router emits `TransferOutAndCall` in the event emission statement, indicating an outbound of `1 ether` toward the requested recipient and final asset.

### Remediation

Validate that the aggregator is a contract and verify post-call delivery. For the legacy V4 interface, if the aggregator returns successfully but the recipient did not receive the expected output, the router should revert so the native value is not permanently transferred to the aggregator and no misleading event is emitted.

```solidity
uint256 _safeAmount = msg.value;
require(aggregator.code.length != 0, "THORChain_Router: invalid aggregator");
uint256 balanceBefore = finalToken == address(0)
? to.balance
: iERC20(finalToken).balanceOf(to);
(bool erc20Success, ) = aggregator.call{value: _safeAmount}(
abi.encodeWithSignature(
"swapOut(address,address,uint256)",
finalToken,
to,
amountOutMin
)
);
if (erc20Success) {
uint256 balanceAfter = finalToken == address(0)
? to.balance
: iERC20(finalToken).balanceOf(to);
require(
balanceAfter >= balanceBefore &&
balanceAfter - balanceBefore >= amountOutMin,
"THORChain_Router: insufficient swap output"
);
} else {
bool ethSuccess = payable(to).send(_safeAmount);
if (!ethSuccess) {
payable(address(msg.sender)).transfer(_safeAmount);
}
}
```

## Unbound Native ETH Source in `_transferOutV5` Allows Router ETH Drain and Misleading `TransferOut` Logs in `THORChain_Router`

[ethereum/contracts/THORChain_Router.sol#L209-L238](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/ethereum/contracts/THORChain_Router.sol#L209-L238)

```solidity
  function _transferOutV5(TransferOutData memory transferOutPayload) private {
    if (transferOutPayload.asset == address(0)) {
      bool success = transferOutPayload.to.send(transferOutPayload.amount); // Send ETH.
      if (!success) {
        payable(address(msg.sender)).transfer(transferOutPayload.amount); // For failure, bounce back to vault & continue.
      }
    } else {
      _vaultAllowance[msg.sender][
        transferOutPayload.asset
      ] -= transferOutPayload.amount; // Reduce allowance

      (bool success, bytes memory data) = transferOutPayload.asset.call(
        abi.encodeWithSignature(
          "transfer(address,uint256)",
          transferOutPayload.to,
          transferOutPayload.amount
        )
      );

      require(success && (data.length == 0 || abi.decode(data, (bool))));
    }

    emit TransferOut(
      msg.sender,
      transferOutPayload.to,
      transferOutPayload.asset,
      transferOutPayload.amount,
      transferOutPayload.memo
    );
  }
```

### Synopsis

`THORChain_Router._transferOutV5` sends native ETH using `transferOutPayload.amount` without verifying that the caller supplied that ETH via `msg.value` or owns an ETH allowance. Any caller can spend pre-existing router ETH and emit a normal `TransferOut` log.

### Technical Details

In the highlighted `_transferOutV5` function, the ERC20 branch deducts `_vaultAllowance[msg.sender][asset]` before transferring tokens. The native ETH branch has no equivalent accounting or funding validation.

In the native ETH handling branch of `_transferOutV5` (the `if (transferOutPayload.asset == address(0))` condition and its body), the function executes:

- native ETH transfer based solely on `transferOutPayload.amount`;
- no check that `msg.value == transferOutPayload.amount`;
- no cumulative `msg.value` accounting for batched calls;
- no ETH allowance decrement;
- no restriction that the ETH being sent belongs to `msg.sender`.

`address.send(value)` spends ETH from `address(this).balance`, not specifically from the current call’s `msg.value`. Therefore, if the router holds any native ETH balance, a non-privileged caller can call the public V5 transfer wrapper with `msg.value == 0`, set `asset == address(0)`, and cause `_transferOutV5` to send router-held ETH to an arbitrary recipient.

The event emitted in the `TransferOut` emission call in `_transferOutV5` then reports a normal outbound:

```solidity
TransferOut(msg.sender, transferOutPayload.to, address(0), transferOutPayload.amount, memo)
```

This creates event/accounting divergence because the emitted `vault` field is `msg.sender`, but the ETH did not have to be funded by that sender or by a tracked vault balance. Off-chain systems relying on the router event can observe an apparently valid outbound even though the underlying value was taken from unrelated ETH already present in the router.

The root cause is the missing binding between native ETH outbounds and the current call’s supplied ETH budget.

### Verification Checklist

To verify this vulnerability from code and documentation only, check the following:

- Confirm that `_transferOutV5` handles native ETH when `transferOutPayload.asset == address(0)` in the `if (transferOutPayload.asset == address(0))` condition.
- Confirm that the `transferOutPayload.to.send(transferOutPayload.amount)` call in `_transferOutV5` sends from the router contract balance.
- Confirm there is no `require(msg.value == transferOutPayload.amount)` or equivalent ETH-budget check in the native ETH handling branch of `_transferOutV5`.
- Confirm there is no `_vaultAllowance[msg.sender][address(0)]` decrement in the ETH branch, unlike the ERC20 branch where `_vaultAllowance[msg.sender][transferOutPayload.asset] -= transferOutPayload.amount` is performed.
- Confirm the `TransferOut` event emitted in `_transferOutV5` emits `msg.sender` as the vault and `transferOutPayload.amount` as the amount regardless of whether that amount was supplied by `msg.sender`.
- Confirm from surrounding context that `_transferOutV5` is reachable through public/external V5 transfer functions.
- Confirm that native ETH can exist in the router balance, including through accidental transfers, overpayment, or forced ETH via `selfdestruct`.

### Assumptions and Preconditions

- `_transferOutV5` is reachable through the router’s public V5 outbound entry points.
- The router has a positive native ETH balance before the exploit, from accidental deposits, overpayment, forced ETH, or other residual balance.
- The attacker is not a privileged vault and does not need an ERC20 allowance.
- Off-chain observers treat `TransferOut` logs as outbound evidence according to the documented router/Bifrost flow.
- No admin or owner misbehavior is required.

### Proof of Concept

1. Assume the router has `10 ETH` in its balance.

2. The attacker calls the public V5 transfer wrapper that reaches `_transferOutV5` with:

```solidity
TransferOutData({
    to: payable(attacker),
    asset: address(0),
    amount: 10 ether,
    memo: "OUT:fake-or-targeted-memo"
})
```

and sends:

```solidity
msg.value = 0
```

3. Execution enters `_transferOutV5`.

4. In the `if (transferOutPayload.asset == address(0))` condition of `_transferOutV5`, the native ETH branch is selected.

5. In the `transferOutPayload.to.send(transferOutPayload.amount)` call of `_transferOutV5`, the router executes:

```solidity
transferOutPayload.to.send(transferOutPayload.amount)
```

This sends `10 ETH` from `address(this).balance` to the attacker, even though the attacker supplied no ETH.

6. No ETH allowance is decremented and no `msg.value` validation is performed.

7. In the `TransferOut` event emission of `_transferOutV5`, the router emits a normal `TransferOut` event showing:

```solidity
vault = attacker
to = attacker
asset = address(0)
amount = 10 ether
memo = "OUT:fake-or-targeted-memo"
```

8. The attacker has drained the router’s pre-existing ETH balance, and off-chain observers see a standard outbound event that is not tied to actual caller funding.

### Remediation

Bind native ETH outbounds to an explicit per-call ETH budget. The preferred fix is:

- initialize an ETH budget from `msg.value` in the public single/batch entry point;
- pass the remaining ETH budget into `_transferOutV5`;
- require each native ETH item to consume no more than the remaining budget;
- decrement the remaining budget after each native ETH item;
- require no unconsumed ETH remains after processing.

Corrected helper logic:

```solidity
function _transferOutV5(
TransferOutData memory transferOutPayload,
uint256 ethRemaining
) private returns (uint256 ethSpent) {
if (transferOutPayload.asset == address(0)) {
require(
transferOutPayload.amount <= ethRemaining,
"THORChain_Router: insufficient ETH supplied"
);
(bool success, ) = transferOutPayload.to.call{
value: transferOutPayload.amount
}("");
require(success, "THORChain_Router: ETH transfer failed");
ethSpent = transferOutPayload.amount;
```

The public single-transfer caller should pass `msg.value` and require the returned `ethSpent` equals `msg.value`. The batch caller should maintain `ethRemaining`, subtract each returned `ethSpent`, and require `ethRemaining == 0` after the loop.

## Fixed-gas vault refund can revert and DoS failed native outbounds in `transferOutAndCall` of `THORChain_Router`

[ethereum/contracts/THORChain_Router.sol#L255-L293](https://github.com/evmbench-org/2024-06-thorchain/blob/dc7c9db428483f283bb0c0f44794d46d0ef750de/ethereum/contracts/THORChain_Router.sol#L255-L293)

```solidity
function transferOutAndCall(
    address payable aggregator,
    address finalToken,
    address to,
    uint256 amountOutMin,
    string memory memo
) public payable nonReentrant {
    uint256 _safeAmount = msg.value;
    (bool erc20Success, ) = aggregator.call{value: _safeAmount}(
        abi.encodeWithSignature("swapOut(address,address,uint256)",
            finalToken, to, amountOutMin)
    );
    if (!erc20Success) {
        bool ethSuccess = payable(to).send(_safeAmount);
        if (!ethSuccess) {
            payable(address(msg.sender)).transfer(_safeAmount);
        }
    }
    emit TransferOutAndCall(msg.sender, aggregator, _safeAmount, finalToken, to, amountOutMin, memo);
}
```

### Synopsis

`THORChain_Router.transferOutAndCall` refunds failed native-asset fallbacks to `msg.sender` using Solidity `transfer`. Contract-based vault callers that need more than 2300 gas to receive ETH can make the failure path revert, blocking outbound completion and event emission.

### Technical Details

In `transferOutAndCall`, the router first forwards `msg.value` to the aggregator via the low-level `aggregator.call{value: _safeAmount}` to `swapOut`. If the aggregator call fails, execution enters the fallback path at `if (!erc20Success)` and attempts to send the native asset directly to `to` using `payable(to).send(_safeAmount)`.

If that direct recipient fallback also fails, the router attempts to refund the native asset to `msg.sender` via `payable(address(msg.sender)).transfer(_safeAmount)`:

- `transfer` forwards only 2300 gas.
- `transfer` reverts if the recipient cannot receive ETH within that stipend.
- `msg.sender` is the vault/caller of the outbound path.
- The function has no non-reverting fallback or pull-refund accounting if this refund fails.

Therefore, when the vault/caller is a contract wallet, multisig, proxy, or any contract with a `receive()` / `fallback()` requiring more than 2300 gas, the refund `transfer` to `msg.sender` reverts the entire `transferOutAndCall` transaction.

This converts an intended non-reverting failed-swap recovery path into a deterministic denial of service. The native outbound is not delivered to the recipient, the refund does not complete, and the `TransferOutAndCall` event emission is never executed because the transaction reverts before reaching it.

### Verification Checklist

A security engineer can verify the issue statically by checking:

- The `if (!erc20Success)` condition only enters the fallback branch when the aggregator low-level `call` fails.
- The `payable(to).send(_safeAmount)` uses `send`, so recipient contracts that reject ETH or need more than 2300 gas cause `ethSuccess == false`.
- The `payable(address(msg.sender)).transfer(_safeAmount)` uses Solidity `transfer` to refund `msg.sender`.
- `transfer` is a fixed-2300-gas ETH transfer and reverts on failure.
- There is no try/catch, pull-payment refund accounting, or alternative recovery path around the refund `transfer` to `msg.sender`.
- There is no restriction in the highlighted function requiring `msg.sender` to be an EOA.
- The `emit TransferOutAndCall(...)` occurs after the refund path, so it is skipped if the refund `transfer` to `msg.sender` reverts.

### Assumptions and Preconditions

- `transferOutAndCall` is used for native-asset outbounds.
- The low-level aggregator `swapOut` call can fail, for example due to slippage, unsupported output asset, or downstream revert.
- The fallback recipient `to` is a contract that cannot receive ETH through the 2300-gas `payable(to).send(_safeAmount)`.
- The vault/caller represented by `msg.sender` is a contract-based account whose ETH receive path requires more than 2300 gas.
- The protocol relies on a successful router transaction and emitted `TransferOutAndCall` event to progress outbound processing.
- The vault/caller is honest; the failure arises from contract-recipient incompatibility, not privileged abuse.

### Proof of Concept

1. Use a contract-based vault/caller with a gas-consuming `receive()` function:

```solidity
contract ContractVault {
    THORChain_Router router;
    uint256 public stored;

    receive() external payable {
        stored = 1; // Requires more than 2300 gas.
    }

    function execute(
        address payable aggregator,
        address finalToken,
        address to
    ) external payable {
        router.transferOutAndCall{value: msg.value}(
            aggregator,
            finalToken,
            to,
            1,
            "OUT:poc"
        );
    }
}
```

2. Use an aggregator that fails the swap call:

```solidity
contract RevertingAggregator {
    function swapOut(address, address, uint256) external payable {
        revert("swap failed");
    }
}
```

3. Use a recipient contract that cannot receive ETH through `send`:

```solidity
contract GasHeavyRecipient {
    uint256 public stored;

    receive() external payable {
        stored = 1; // Causes 2300-gas send to fail.
    }
}
```

4. `ContractVault.execute{value: 1 ether}` calls `transferOutAndCall`.

5. The low-level `aggregator.call{value: _safeAmount}` to `RevertingAggregator.swapOut` with `1 ether` fails and returns `erc20Success == false`.

6. The `payable(to).send(_safeAmount)` attempts to send `1 ether` to `GasHeavyRecipient`; the 2300-gas `send` fails and returns `ethSuccess == false`.

7. The `payable(address(msg.sender)).transfer(_safeAmount)` attempts to refund `1 ether` to `ContractVault`.

8. `ContractVault.receive()` requires more than 2300 gas, so the `transfer` reverts.

9. The entire `transferOutAndCall` transaction reverts before the `TransferOutAndCall` event emission, so no outbound event is emitted and the failed outbound cannot be completed through this path.

### Remediation

Replace the fixed-gas `transfer` refund with a low-level `call` so contract-based vaults can execute normal receive logic. Keep explicit success handling so funds are not silently trapped.

```solidity
(bool refundSuccess, ) = payable(address(msg.sender)).call{value: _safeAmount}("");
require(refundSuccess, "THORChain_Router: vault refund failed");
```

For a more robust design, consider pull-based refund accounting for failed vault refunds, but the immediate fix is to remove the 2300-gas stipend dependency from the vault refund path.

## Shared Uniswap V3 position `collect()` sweeps other NFT holders’ accrued fees to `FEE_TAKER` in `claim` of `ILOPool`

[src/ILOPool.sol#L183-L261](https://github.com/evmbench-org/2024-06-vultisig/blob/60056cfffd7722ff71b511934a5daa1075d20ca2/src/ILOPool.sol#L183-L261)

```solidity
    function claim(uint256 tokenId) external payable override isAuthorizedForToken(tokenId) returns (uint256 amount0, uint256 amount1) {
        uint128 liquidity2Claim = _claimableLiquidity(tokenId);
        IUniswapV3Pool pool = IUniswapV3Pool(_cachedUniV3PoolAddress);
        Position storage position = _positions[tokenId];
        // Burn updates/credits fees for entire shared position
        (amount0, amount1) = pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim);
        // ... deduct platform fee ...
        // Calc fees for this NFT using its snapshot vs aggregate
        (,uint256 fg0,uint256 fg1,,) = pool.positions(PositionKey.compute(address(this), TICK_LOWER, TICK_UPPER));
        uint256 fees0 = FullMath.mulDiv(fg0 - position.feeGrowthInside0LastX128, position.liquidity, FixedPoint128.Q128);
        uint256 fees1 = FullMath.mulDiv(fg1 - position.feeGrowthInside1LastX128, position.liquidity, FixedPoint128.Q128);
        // ... deduct performance fee ...
        amount0 += fees0; amount1 += fees1;
        position.feeGrowthInside0LastX128 = fg0;
        position.feeGrowthInside1LastX128 = fg1;
        position.liquidity -= liquidity2Claim;
        // Collect ALL owed tokens for shared position
        (uint128 collected0, uint128 collected1) = pool.collect(address(this), TICK_LOWER, TICK_UPPER, type(uint128).max, type(uint128).max);
        // Transfer only this NFT's share to owner
        TransferHelper.safeTransfer(_cachedPoolKey.token0, ownerOf(tokenId), amount0);
        TransferHelper.safeTransfer(_cachedPoolKey.token1, ownerOf(tokenId), amount1);
        // VULN: Remainder incl. other NFTs' fees -> FEE_TAKER
        address feeTaker = IILOManager(MANAGER).FEE_TAKER();
        TransferHelper.safeTransfer(_cachedPoolKey.token0, feeTaker, collected0 - amount0);
        TransferHelper.safeTransfer(_cachedPoolKey.token1, feeTaker, collected1 - amount1);
    }
```

### Synopsis

`ILOPool.claim` settles one NFT holder but calls Uniswap V3 `collect()` for the entire shared position and sends the unallocated remainder to `FEE_TAKER`. Any claimant can therefore sweep fees accrued for other NFTs, causing fee loss and claim-order-dependent reverts.

### Technical Details

`ILOPool` represents multiple NFT positions over a single shared Uniswap V3 position keyed by:

```solidity
PositionKey.compute(address(this), TICK_LOWER, TICK_UPPER)
```

In `claim`, the contract burns only the current NFT’s claimable liquidity, then calculates the current NFT holder’s fee entitlement from the difference between the aggregate Uniswap fee-growth snapshot and the NFT’s stored snapshot.

The problem is that Uniswap V3 accounting is done at the aggregate position level. A call to `pool.burn(...)`, including a zero-liquidity burn, updates the shared Uniswap position and credits all fees accrued by the whole shared position into `tokensOwed`, not only the fees belonging to the currently claiming NFT.

The highlighted code then performs:

```solidity
pool.collect(address(this), ..., type(uint128).max, type(uint128).max)
```

This collects all currently owed tokens for the shared Uniswap position. However, only the current NFT’s calculated `amount0` / `amount1` is transferred to the NFT owner. The remaining collected balance is treated as protocol fee and transferred to `FEE_TAKER`:

```solidity
TransferHelper.safeTransfer(_cachedPoolKey.token0, feeTaker, amountCollected0 - amount0);
TransferHelper.safeTransfer(_cachedPoolKey.token1, feeTaker, amountCollected1 - amount1);
```

That remainder is not exclusively protocol fee. It can include other NFT holders’ accrued Uniswap fees that were materialized by the aggregate `burn` / `collect` operation but have not yet been individually claimed.

As a result:

1. The first claimant after fees accrue can trigger collection of everyone’s fees.
2. The claimant receives only their own calculated portion.
3. Other NFT holders’ fee portions are transferred to `FEE_TAKER`.
4. Their personal fee-growth snapshots remain stale.
5. Later claims by those holders may revert or attempt to pay already-swept fees from newly collected funds, making payouts claim-order dependent.

The root cause is the unconditional collection of the entire shared Uniswap V3 position and classification of the residual as fee-taker revenue.

### Verification Checklist

A security engineer can verify this issue statically by checking:

- `ILOPool` uses one shared Uniswap V3 position owned by `address(this)` for all NFTs.
- `claim()` computes fees for only one `tokenId` using `_positions[tokenId]`.
- `pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim)` is called on the shared position.
- Uniswap V3 `burn()` updates and credits fees for the whole shared position, not for an individual NFT.
- The `pool.collect(address(this), TICK_LOWER, TICK_UPPER, type(uint128).max, type(uint128).max)` call collects all owed tokens for the shared position.
- The `TransferHelper.safeTransfer(_cachedPoolKey.token0, ownerOf(tokenId), amount0)` and `TransferHelper.safeTransfer(_cachedPoolKey.token1, ownerOf(tokenId), amount1)` calls transfer only the current NFT’s calculated amount to the NFT owner.
- The `TransferHelper.safeTransfer(_cachedPoolKey.token0, feeTaker, amountCollected0-amount0)` and `TransferHelper.safeTransfer(_cachedPoolKey.token1, feeTaker, amountCollected1-amount1)` calls transfer `amountCollected - amount` to `FEE_TAKER`.
- There is no accounting bucket preserving unclaimed fees belonging to other NFT holders.
- Other NFT holders’ `feeGrowthInside{0,1}LastX128` snapshots are not updated when their fees are swept by another claimant.

### Assumptions and Preconditions

- The ILO pool has successfully launched.
- Multiple NFTs share the same Uniswap V3 position.
- The shared Uniswap V3 position has accrued swap fees.
- At least one NFT holder calls `claim`.
- Other NFT holders have not yet claimed the same accrued fee interval.
- `FEE_TAKER` is a normal protocol fee recipient and is not expected to receive investor fee entitlement.

### Proof of Concept

1. Alice and Bob each hold an ILO NFT backed by liquidity in the same Uniswap V3 position.
2. The shared Uniswap V3 position earns swap fees.
3. Alice calls `claim(aliceTokenId)`.
4. `claim()` calls `pool.burn(...)`, which updates the aggregate Uniswap position and credits all accrued fees for the shared position.
5. Alice’s individual fee entitlement is calculated using Alice’s stored snapshot.
6. `claim()` calls `pool.collect(..., max, max)`, collecting all owed fees for the aggregate position, including Bob’s accrued fees.
7. Alice receives only Alice’s calculated claim amount.
8. The remainder, which includes Bob’s accrued fees, is transferred to `FEE_TAKER`.
9. Bob’s stored fee-growth snapshot is not updated.
10. When Bob later calls `claim(bobTokenId)`, his accounting still expects the swept fees, but those tokens are no longer available. His claim can revert or be paid from later unrelated collections, depending on subsequent fee accrual.

### Remediation

Do not transfer the entire `amountCollected - amount` remainder to `FEE_TAKER`. The contract must separate:

- current claimant principal;
- current claimant performance/platform fee;
- current claimant net fee entitlement;
- unclaimed fee entitlement belonging to other NFTs.

A robust fix is to maintain global fee accounting for the shared position and only collect/settle amounts attributable to the claiming NFT, while preserving the remaining collected tokens in internal accounting instead of forwarding them to `FEE_TAKER`.

At minimum, the highlighted settlement logic should not classify the full residual as protocol fee.

```solidity
(uint256 fees0AfterFee, uint256 fees1AfterFee) = _deductFees(fees0, fees1, _project.performanceFee);
uint256 performanceFee0 = fees0 - fees0AfterFee;
uint256 performanceFee1 = fees1 - fees1AfterFee;
amount0 += fees0AfterFee;
amount1 += fees1AfterFee;
position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;
position.liquidity = positionLiquidity - liquidity2Claim;
emit DecreaseLiquidity(tokenId, liquidity2Claim, amount0, amount1);
address feeTaker = IILOManager(MANAGER).FEE_TAKER();
TransferHelper.safeTransfer(_cachedPoolKey.token0, feeTaker, performanceFee0);
TransferHelper.safeTransfer(_cachedPoolKey.token1, feeTaker, performanceFee1);
```

This minimal change prevents forwarding other users’ collected fees as protocol fees, but a complete production fix should also add explicit internal accounting for collected-but-unclaimed fees per NFT or redesign the system so each NFT owns an isolated Uniswap V3 position.

## Aggregate Uniswap fee accrual is misaccounted during per-NFT `claim` in `ILOPool.claim`

[src/ILOPool.sol#L183-L261](https://github.com/evmbench-org/2024-06-vultisig/blob/60056cfffd7722ff71b511934a5daa1075d20ca2/src/ILOPool.sol#L183-L261)

```solidity
    function claim(uint256 tokenId) external returns (uint256 amount0, uint256 amount1) {
        require(_launchSucceeded, "PNL");
        uint128 liquidity2Claim = _claimableLiquidity(tokenId);
        IUniswapV3Pool pool = IUniswapV3Pool(_cachedUniV3PoolAddress);
        Position storage position = _positions[tokenId];
        {
            // IILOManager.Project memory _project = ...;
            uint128 positionLiquidity = position.liquidity;
            require(positionLiquidity >= liquidity2Claim);
            (amount0, amount1) = pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim); // accrues fees for entire shared position
            (amount0, amount1) = _deductFees(amount0, amount1, _project.platformFee);
            bytes32 positionKey = PositionKey.compute(address(this), TICK_LOWER, TICK_UPPER); // shared key
            (, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , ) = pool.positions(positionKey);
            uint256 fees0 = FullMath.mulDiv(feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128, positionLiquidity, FixedPoint128.Q128); // only this tokenId's share
            uint256 fees1 = FullMath.mulDiv(feeGrowthInside1LastX128 - position.feeGrowthInside1LastX128, positionLiquidity, FixedPoint128.Q128);
            (fees0, fees1) = _deductFees(fees0, fees1, _project.performanceFee);
            amount0 += fees0;
            amount1 += fees1;
            position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
            position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;
            position.liquidity = positionLiquidity - liquidity2Claim;
            // emit DecreaseLiquidity(...);
        }
        (uint128 amountCollected0, uint128 amountCollected1) = pool.collect(address(this), TICK_LOWER, TICK_UPPER, type(uint128).max, type(uint128).max); // collects all tokensOwed
        // emit Collect(...);
        // TransferHelper.safeTransfer to ownerOf(tokenId), amount0/1;
        address feeTaker = IILOManager(MANAGER).FEE_TAKER();
        TransferHelper.safeTransfer(_cachedPoolKey.token0, feeTaker, amountCollected0 - amount0); // excess (other NFTs' fees) to feeTaker
        TransferHelper.safeTransfer(_cachedPoolKey.token1, feeTaker, amountCollected1 - amount1);
        // emit Claim(...);
    }
```

### Synopsis

`ILOPool.claim` burns liquidity from one shared Uniswap V3 position for a single NFT, but Uniswap accrues fees for the entire aggregate position. The function accounts only the caller’s fee share, causing other tokenIds’ accrued fees to be collected and misallocated, creating claim-order-dependent loss and DoS.

### Technical Details

All ILO NFTs represent shares of the same Uniswap V3 core position, identified by:

```solidity
PositionKey.compute(address(this), TICK_LOWER, TICK_UPPER)
```

In the `claim` function, the call to `pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim)`

In Uniswap V3, `burn`, including `burn(..., 0)`, does not accrue fees only for the burned liquidity or only for the calling NFT. It updates the single aggregate Uniswap position and credits `tokensOwed` for the entire liquidity held by `address(this)` in that tick range.

However, the fee calculations using `FullMath.mulDiv(feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128, positionLiquidity, FixedPoint128.Q128)` (and similarly for token1) only for the currently claimed NFT:

```solidity
feeDelta * positionLiquidity / Q128
```

Only the current tokenId’s snapshot is updated afterward. Other tokenIds’ snapshots remain stale even though their accrued fees were already materialized into the aggregate Uniswap position’s `tokensOwed`.

As a result, the current claim realizes fees belonging to all NFTs, but the highlighted accounting recognizes only the current NFT’s share. The unaccounted portion is later treated as excess/protocol remainder rather than being reserved for the other NFT holders. Those other holders still have old snapshots and will later attempt to claim fees that have already been collected, causing either fee loss, payment from unrelated future proceeds, or claim reverts due to insufficient available tokens.

The root cause is using a shared Uniswap V3 position as if `burn` were a per-NFT fee checkpoint, while the fee accounting in the `FullMath.mulDiv` calls for fees0 and fees1 is per-tokenId.

### Verification Checklist

A security engineer can verify this issue statically by checking:

- `ILOPool` represents multiple NFTs as shares of one Uniswap V3 position.
- The computation of the Uniswap position key using `PositionKey.compute(address(this), TICK_LOWER, TICK_UPPER)` in `claim`, not `tokenId`.
- The call to `pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim)` during a single NFT claim.
- Uniswap V3 `burn` updates fee growth and `tokensOwed` for the entire core position owned by `address(this)`.
- The fee calculations using `FullMath.mulDiv(feeGrowthInside{0,1}LastX128 - position.feeGrowthInside{0,1}LastX128, positionLiquidity, FixedPoint128.Q128)` only for `positionLiquidity` of the current tokenId.
- Only the current tokenId’s fee snapshot (`position.feeGrowthInside{0,1}LastX128`) is updated after this calculation.
- No highlighted logic reserves the remaining aggregate fees for other tokenIds.
- The check `require(positionLiquidity >= liquidity2Claim)` allows `liquidity2Claim == 0`, so a holder can trigger aggregate fee realization even when no principal is vested.

### Assumptions and Preconditions

- The ILO pool has launched successfully.
- At least two NFTs have nonzero liquidity shares in the same ILO pool.
- Trading fees have accrued in the shared Uniswap V3 position.
- The attacker owns, or is approved for, any valid ILO NFT.
- Standard Uniswap V3 pool behavior is used: `burn` accrues fees for the full aggregate position.
- Manager/admin accounts are honest; no privileged abuse is required.

### Proof of Concept

1. Two users, Alice and Bob, each own an ILO NFT representing 50% of the shared Uniswap V3 liquidity.
2. Assume both local fee snapshots are `0`.
3. Swaps occur in the Uniswap V3 pool, generating `100 token0` fees for the aggregate ILO position.
   - Alice’s fair share is `50 token0`.
   - Bob’s fair share is `50 token0`.
4. Alice calls `claim(aliceTokenId)` while `liquidity2Claim == 0` or any small positive amount.
5. The call to `pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim)` in `claim`.
   - Uniswap credits the full `100 token0` fees to the aggregate position.
6. The fee calculations using `FullMath.mulDiv(...)` compute only Alice’s share:
   - `fees0 = 50 token0`.
7. Alice receives her `50 token0`.
8. Bob’s `50 token0` was already realized in the aggregate Uniswap accounting, but Bob’s local snapshot was not updated and no reserve was created for him.
9. When Bob later calls `claim(bobTokenId)`, his stale snapshot still makes the contract calculate `50 token0` as claimable.
10. Those tokens are no longer available from the Uniswap position. Bob’s claim may revert or be paid from unrelated future proceeds, depending on later pool activity.

A dust-sized NFT holder can repeat this pattern to force aggregate fee realization and misallocation of other holders’ accrued fees.

### Remediation

The claim logic must not treat aggregate Uniswap fees as if they belong only to the current tokenId. The preferred fix is to collect only the current claimant’s gross entitlement plus the protocol fees attributable to that claimant, leaving other tokenIds’ accrued fees in the Uniswap position or in an explicit internal reserve.

Corrected code pattern:

```solidity
uint256 feeAmount0;
uint256 feeAmount1;
uint256 amount0ToCollect;
uint256 amount1ToCollect;
{
IILOManager.Project memory _project = IILOManager(MANAGER).project(address(pool));

uint128 positionLiquidity = position.liquidity;
require(positionLiquidity >= liquidity2Claim);

(uint256 burnAmount0, uint256 burnAmount1) = pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim);

uint256 platformFee0 = FullMath.mulDiv(burnAmount0, _project.platformFee, BPS);
uint256 platformFee1 = FullMath.mulDiv(burnAmount1, _project.platformFee, BPS);

bytes32 positionKey = PositionKey.compute(address(this), TICK_LOWER, TICK_UPPER);

(, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , ) = pool.positions(positionKey);

uint256 grossFees0 = FullMath.mulDiv(
feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128,
positionLiquidity,
FixedPoint128.Q128
);

uint256 grossFees1 = FullMath.mulDiv(
feeGrowthInside1LastX128 - position.feeGrowthInside1LastX128,
positionLiquidity,
FixedPoint128.Q128
);

uint256 performanceFee0 = FullMath.mulDiv(grossFees0, _project.performanceFee, BPS);
uint256 performanceFee1 = FullMath.mulDiv(grossFees1, _project.performanceFee, BPS);

amount0 = burnAmount0 - platformFee0 + grossFees0 - performanceFee0;
amount1 = burnAmount1 - platformFee1 + grossFees1 - performanceFee1;

feeAmount0 = platformFee0 + performanceFee0;
feeAmount1 = platformFee1 + performanceFee1;

amount0ToCollect = amount0 + feeAmount0;
amount1ToCollect = amount1 + feeAmount1;

require(amount0ToCollect <= type(uint128).max && amount1ToCollect <= type(uint128).max, "CTO");

position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;

position.liquidity = positionLiquidity - liquidity2Claim;
emit DecreaseLiquidity(tokenId, liquidity2Claim, amount0, amount1);
}
(uint128 amountCollected0, uint128 amountCollected1) = pool.collect(
address(this),
TICK_LOWER,
TICK_UPPER,
uint128(amount0ToCollect),
uint128(amount1ToCollect)
);
require(amountCollected0 == amount0ToCollect && amountCollected1 == amount1ToCollect, "IC");
emit Collect(tokenId, address(this), amountCollected0, amountCollected1);

TransferHelper.safeTransfer(_cachedPoolKey.token0, ownerOf(tokenId), amount0);
TransferHelper.safeTransfer(_cachedPoolKey.token1, ownerOf(tokenId), amount1);

emit Claim(ownerOf(tokenId), tokenId, liquidity2Claim, amount0, amount1, position.feeGrowthInside0LastX128, position.feeGrowthInside1LastX128);

address feeTaker = IILOManager(MANAGER).FEE_TAKER();
TransferHelper.safeTransfer(_cachedPoolKey.token0, feeTaker, feeAmount0);
TransferHelper.safeTransfer(_cachedPoolKey.token1, feeTaker, feeAmount1);
```

Alternatively, keep collecting all aggregate fees, but then the contract must maintain explicit per-position or global accumulator accounting and reserve unclaimed fees for other tokenIds instead of forwarding residual collected balances away.

## Aggregate Uniswap Position Max-Collect Misattributes Other NFT Holders’ Fees in `claim` of `ILOPool`

[src/ILOPool.sol#L183-L261](https://github.com/evmbench-org/2024-06-vultisig/blob/60056cfffd7722ff71b511934a5daa1075d20ca2/src/ILOPool.sol#L183-L261)

```solidity
/// @inheritdoc IILOPool
function claim(uint256 tokenId)
    external
    payable
    override
    returns (uint256 amount0, uint256 amount1)
{
    require(_launchSucceeded, "PNL");

    uint128 liquidity2Claim = _claimableLiquidity(tokenId);
    IUniswapV3Pool pool = IUniswapV3Pool(_cachedUniV3PoolAddress);
    Position storage position = _positions[tokenId];
    {
        // ... project and deductFees setup ...
        uint128 positionLiquidity = position.liquidity;
        require(positionLiquidity >= liquidity2Claim);

        (amount0, amount1) = pool.burn(TICK_LOWER, TICK_UPPER, liquidity2Claim);
        (amount0, amount1) = _deductFees(amount0, amount1, _project.platformFee);

        bytes32 positionKey = PositionKey.compute(address(this), TICK_LOWER, TICK_UPPER);
        (, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , ) = pool.positions(positionKey);
        uint256 fees0 = FullMath.mulDiv(feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128, positionLiquidity, FixedPoint128.Q128);
        uint256 fees1 = FullMath.mulDiv(feeGrowthInside1LastX128 - position.feeGrowthInside1LastX128, positionLiquidity, FixedPoint128.Q128);
        (fees0, fees1) = _deductFees(fees0, fees1, _project.performanceFee);
        amount0 += fees0; amount1 += fees1;

        position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
        position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;
        position.liquidity = positionLiquidity - liquidity2Claim;
        // emit DecreaseLiquidity
    }
    (uint128 amountCollected0, uint128 amountCollected1) = pool.collect(
        address(this), TICK_LOWER, TICK_UPPER, type(uint128).max, type(uint128).max
    );
    // emit Collect

    // TransferHelper.safeTransfer to ownerOf(tokenId), amount0/1
    // emit Claim

    address feeTaker = IILOManager(MANAGER).FEE_TAKER();
    TransferHelper.safeTransfer(_cachedPoolKey.token0, feeTaker, amountCollected0 - amount0);
    TransferHelper.safeTransfer(_cachedPoolKey.token1, feeTaker, amountCollected1 - amount1);
