        poolData.loanLookup[params.nftAsset][params.nftTokenIds[nidx]];
      DataTypes.GroupData storage debtGroupData =
        debtAssetData.groupLookup[loanData.reserveGroup];
      // ERC721TokenData tokenData = ...

