      require(block.timestamp > auctionEndTimestamp, Errors.ISOLATE_BID_AUCTION_DURATION_NOT_END);

      // ... normalizedIndex, borrowAmount = loanData.scaledAmount.rayMul(...), extra/remain calc ...
      // burn borrow: VaultLogic.erc20DecreaseIsolateScaledBorrow(...)
      // remain to borrower, totals +=, delete loanData ...
    }

    // ... total check: (totalBidAmount + totalExtraAmount) >= totalBorrowAmount ...
    // interest rates update, bid to liquidity: VaultLogic.erc20TransferOutBidAmountToLiqudity(...)

    if (/* vars.totalExtraAmount */ > 0) {
      VaultLogic.erc20TransferInLiquidity(debtAssetData, params.msgSender, /* totalExtraAmount */);
    }

