        s := shr(1, add(div(x, s), s))
        s := shr(1, add(div(x, s), s))
        s := shr(1, add(div(x, s), s))
        s := shr(1, add(div(x, s), s))
        s := shr(1, add(div(x, s), s))
        s := shr(1, add(div(x, s), s))
        roundedDownResult := div(x, s)
