if s {
for { } lt(s, MIN_M_DIGIT_NUMBER) { } { s := mul(s, BASE) aExp := sub(aExp, 1) }
for { } gt(s, MAX_M_DIGIT_NUMBER) { } { aExp := add(aExp, 1) s := div(s, BASE) }
