        // e.g.: poolExposure0 = int256(shortPremium.rightSlot()) - int256(longPremium.rightSlot());
        //       if (isLong) { poolExposure0 -= int256(amount0); ... } else { += }
        //       poolExposure0 += int256(collateralToken0.previewRedeem(...));
        // ...
        // Convert to underlying, preserving sign
        if (address(pools[i].token0) != underlyingToken) {
            // TWAP validation
            // ...
