            // TWAP validation
            // ...
            uint160 conversionPrice = Math.getSqrtRatioAtTick(pools[i].isUnderlyingToken0InOracle1 ? PanopticMath.twapFilter(pools[i].oracle1, pools[i].twapWindow) : -PanopticMath.twapFilter(pools[i].oracle1, pools[i].twapWindow));
            poolExposure1 = PanopticMath.convert1to0(poolExposure1, conversionPrice);
        }
        // VULN: Per-pool max(0) prevents negative pools from offsetting positive ones
        nav += uint256(Math.max(poolExposure0 + poolExposure1, 0));
